const e=["Dieu","Crépuscule","Religion"],t="Là où Cione ouvre une porte, Cirana la referme.",n="Déesse du Crépuscule",s=["Cirana représente le Crépuscule.","Elle incarne les fins, les transitions et les instants où une chose cesse d'être ce qu'elle était sans être encore devenue autre chose.","Comme Cione, elle appartient aux divinités liées aux passages.","Mais là où Cione regarde vers ce qui commence, Cirana regarde vers ce qui s'achève.","Le Crépuscule n'est cependant pas considéré comme un symbole de mort.","Il est un moment de transition."],i=[{label:"Domaines",value:"Crépuscule"},{label:"Symboles",value:"Un soleil couchant, une lune naissante, une ligne d'horizon, une fleur qui se referme, un voile, une lanterne"}],r=[{title:"La fin",title_border:"#e8553d",type:"text",content:["Pour les fidèles de Cirana, une fin n'est pas nécessairement un échec.","Certaines choses doivent se terminer.","Une journée.","Un voyage.","Une guerre.","Une relation.","Une époque.","Refuser toute fin revient parfois à empêcher quelque chose de nouveau d'exister.","Cirana enseigne donc l'acceptation du changement, sans pour autant demander aux mortels de renoncer à ce qu'ils aiment."]},{title:"Le culte de Cirana",title_border:"#c2660a",type:"text",content:["Les temples de Cirana sont souvent ouverts vers l'ouest.","Ses fidèles se réunissent au coucher du soleil lors de cérémonies importantes.","Son culte accompagne notamment :"]},{title:"",type:"list",content:["Les départs","Les funérailles","Les changements de saison","La fin des guerres","Les commémorations","Les moments de transition"]},{title:"",type:"text",content:"Certains voyageurs adressent une dernière prière à Cirana avant de quitter une ville."},{title:"Cirana et Cione",title_border:"#6f9fd8",type:"text",content:["Cirana est traditionnellement associée à Cione.","Elles représentent deux moments d'un même cycle.","Cione annonce le commencement.","Cirana annonce la fin.","Certaines traditions les présentent comme deux sœurs.","D'autres affirment qu'elles ne sont que deux visages d'une même divinité.","Aucune version n'est considérée comme universellement vraie.","Ce qui demeure certain est leur complémentarité."]},{title:"Cirana et Fauscht",title_border:"#e8553d",type:"text",content:["Cirana possède également un lien symbolique avec Fauscht.","Le Crépuscule rappelle la fin, mais ne représente pas la Mort.","Il marque plutôt le moment où une existence passe d'un état à un autre.","Pour certains cultes funéraires, le coucher du soleil symbolise ainsi le départ d'un mort vers ce qui vient après la vie.","Cette interprétation reste une tradition mortelle.","Fauscht lui-même n'a jamais expliqué publiquement ce qui attend les morts."]},{title:"Cirana et Riannedos",title_border:"#c2660a",type:"text",content:["Le Crépuscule rappelle également le passage du Temps.","Chaque jour disparaît pour laisser place au suivant.","Ainsi, les fidèles de Cirana considèrent parfois le coucher du soleil comme une petite leçon donnée par Riannedos :","rien ne demeure exactement comme il était."]},{title:"Symboles",title_border:"#6f9fd8",type:"text",content:"Cirana est généralement représentée par :"},{title:"",type:"list",content:["Un soleil couchant","Une lune naissante","Une ligne d'horizon","Une fleur qui se referme","Un voile","Une lanterne"]},{title:"",type:"text",content:"Ses temples utilisent souvent des ouvertures permettant d'observer directement le coucher du soleil."},{title:"Aujourd'hui",title_border:"#e8553d",type:"text",content:["Cirana est particulièrement présente dans les rites de passage.","On la prie lorsqu'une époque se termine ou lorsqu'un individu doit accepter un changement qu'il n'a pas choisi.","Elle est également populaire auprès des voyageurs.","Car voyager signifie souvent laisser quelque chose derrière soi avant de découvrir ce qui attend plus loin.","Cirana ne promet pas que ce qui vient sera meilleur.","Elle rappelle simplement qu'une chose peut être terminée sans que tout soit perdu."]}],a=["Les Dieux","Cione","Fauscht","Riannedos","L’Aube","Le Crépuscule"],o={tags:e,citation:t,surname:n,presentation:s,infos:i,sections:r,related:a};export{t as citation,o as default,i as infos,s as presentation,a as related,r as sections,n as surname,e as tags};
